/** NG-6 API: the lord keeps a promise before its deadline — a payment is paid from the treasury; support is given. */
export function keepPromise(state: GameState, promiseId: string): GameState {
  const diplomacy = diplomacyOf(state);
  const record = diplomacy.promises.find(entry => entry.id === promiseId);
  if (record === undefined || record.status !== "open" || record.promisor !== LORD || state.tick > record.deadline) return state;
  let next = state;
  const amount = record.amount ?? 0;
  if (amount > 0) {
    if (treasuryBalance(state) < amount) return state;
    const posted = postLedgerEntries(state, [{ account: "cash", category: "promise_payment", amount: -amount,
      sourceRefs: [{ type: "claim", id: record.id, detail: record.term }, { type: "actor", id: record.promisee }] }]);
    next = { ...next, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin };
  }
  return settle(next, record.id, "kept");

/** NG-8 API: the will-change answer — a favour paid, support promised, or the new will let stand (it names a rival). */
export function answerWillChange(state: GameState, choice: "favour" | "support_promise" | "let_it_be"): GameState {
  const plan = diplomacyOf(state).marriage;
  if (plan === undefined || plan.stage !== "will_change" || plan.willAnswer !== undefined) return state;
  if (choice === "favour") {
    if (treasuryBalance(state) < WILL_FAVOUR_PENNIES) return state;
    const posted = postLedgerEntries(state, [{ account: "cash", category: "promise_payment", amount: -WILL_FAVOUR_PENNIES,
      sourceRefs: [{ type: "claim", id: plan.claimId, detail: "will_favour" }, { type: "actor", id: COUNTERPART }] }]);
    return withPlan({ ...state, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin },
      { ...plan, stage: "father_ill", willAnswer: choice, events: { ...plan.events, will_dropped: state.tick } });
  }
  if (choice === "support_promise") {
    const made = promise(diplomacyOf(state), { promisor: LORD, promisee: COUNTERPART, term: "political_support", deadline: state.tick + PROMISE_SUPPORT_TICKS,
      witnesses: MARRIAGE_WITNESSES, stake: PROMISE_STAKE, negotiationId: plan.negotiationId });

/** Posts `amount` (positive: into the treasury; negative: out of it, at most what it holds); returns what moved. */
function post(state: GameState, category: LedgerCategory, amount: number, sources: readonly [SourceRef, ...SourceRef[]]): { readonly state: GameState; readonly moved: number } {
  const moved = amount < 0 ? -Math.min(-amount, Math.max(0, treasuryBalance(state))) : amount;
  if (moved === 0) return { state, moved: 0 };
  const posted = postLedgerEntries(state, [{ account: "cash", category, amount: moved, sourceRefs: sources }]);
  return { state: { ...state, treasuryCoin: posted.treasuryCoin, ledger: posted.ledger }, moved };
}

export function answerLegacyPetition(state: GameState, petition: PetitionRecord, response: PetitionResponse | "expired"): GameState {
  const legacy = legacyOf(state);
  if (legacy === undefined) return state;
  let next = withLegacy(state, { ...legacy, answers: { ...legacy.answers, [petition.defId]: response } });
  const l = legacyOf(next)!;
  switch (petition.defId) {
    case ROYAL_TAX_PETITION_ID: {
      if (response !== "accept") break;
      const due = Math.max(B.subsidyMin, Math.min(B.subsidyMax, Math.floor(treasuryBalance(next) * B.subsidyPermille / 1000)));
      const paid = post(next, "royal_subsidy", -due, [{ type: "actor", id: "crown" }, { type: "claim", id: "royal_subsidy", detail: "tenth_and_fifteenth" }]);
      next = withLegacy(paid.state, { ...l, royalSubsidy: l.royalSubsidy - paid.moved });
      break;

if (response === "accept") {
  // LG-2: the mayoralty and the seal to the town (and chapter 4's two lines if it had refused); the fine; the fee farm.
  const held = new Set((next.politics?.rights ?? []).map(right => right.id));
  const lines = [MAYORALTY_RIGHT_ID, BOROUGH_SEAL_RIGHT_ID, MARKET_TOLLS_RIGHT_ID, BRIDGE_TOLLS_RIGHT_ID].filter(id => !held.has(id));
  if (next.politics !== undefined) next = { ...next, politics: { ...next.politics, rights: [...next.politics.rights, ...lines.map(id => ({ id, holder: "townsfolk" as const,
    grantedTick: state.tick, petitionId: petition.id, stallFeePermille: id === MARKET_TOLLS_RIGHT_ID ? 0 : 1000 }))] } };
  next = post(next, "charter_fee", B.charterFine, [TOWN_ACTOR, { type: "right", id: BOROUGH_SEAL_RIGHT_ID, detail: "charter_fine" }]).state;
  if (l.answers[ROYAL_TAX_PETITION_ID] !== "accept") {
    next = post(next, "royal_subsidy", -B.confirmationFine, [{ type: "actor", id: "crown" }, { type: "claim", id: "royal_subsidy", detail: "confirmation" }]).state;
  }
  const mayorCandidate = personOf(next, l.mayorCandidateId);

 * full slot went dry when the alehouses did), else from its nearest alehouse with ale; the alehouses' dues on their sales.
 */
function drinkSeason(state: GameState): GameState {
  const buildings = new Map(state.buildings.map(building => [building.id, building]));
  const houses = [...state.houses];
  const at = new Map(houses.map((house, index) => [house.buildingId, index]));
  const sold = new Map<string, number>();
  let drunk = 0;
  for (const house of [...state.houses].sort((a, b) => a.buildingId.localeCompare(b.buildingId))) {
    if (house.level < 1 || house.residents <= 0) continue;
    const home = buildings.get(house.buildingId);
    if (home === undefined) continue;
    const own = houses[at.get(house.buildingId)!]!;
    const ownSlot = brewingSlot(own);
    if (ownSlot !== null && (ownSlot.stock.ale ?? 0) >= ALE_BALANCE.alePerHouseSeason) {
      houses[at.get(house.buildingId)!] = { ...withSlot(own, { ...ownSlot, stock: { ...ownSlot.stock, ale: (ownSlot.stock.ale ?? 0) - ALE_BALANCE.alePerHouseSeason } }),
        aleUntilTick: state.tick + ALE_BALANCE.aleServedTicks };
      drunk += ALE_BALANCE.alePerHouseSeason;
      continue;
    }
    const stake = houses.filter(entry => isAlehouse(entry) && (brewingSlot(entry)?.stock.ale ?? 0) > 0 && buildings.has(entry.buildingId)
      && buildingFootprintDistance(home, buildings.get(entry.buildingId)!) <= ALE_BALANCE.alehouseReach)
      .sort((a, b) => buildingFootprintDistance(home, buildings.get(a.buildingId)!) - buildingFootprintDistance(home, buildings.get(b.buildingId)!)
        || a.buildingId.localeCompare(b.buildingId))[0];
    if (stake === undefined) continue;
    const slot = brewingSlot(stake)!;
    const drink = Math.min(ALE_BALANCE.alePerHouseSeason, slot.stock.ale ?? 0);
    if (drink <= 0) continue;
    houses[at.get(stake.buildingId)!] = withSlot(stake, { ...slot, stock: { ...slot.stock, ale: (slot.stock.ale ?? 0) - drink } });
    const drinker = houses[at.get(house.buildingId)!]!;
    houses[at.get(house.buildingId)!] = { ...drinker, aleUntilTick: state.tick + ALE_BALANCE.aleServedTicks };
    sold.set(stake.buildingId, (sold.get(stake.buildingId) ?? 0) + drink);
    drunk += drink;
  }
  const next = counted({ ...state, houses }, { drunk, sold: [...sold.values()].reduce((sum, casks) => sum + casks, 0) });
  if (sold.size === 0) return next;
  const postings: LedgerPosting[] = [];
  for (const [id, casks] of [...sold.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    const dues = Math.ceil(casks * ALE_BALANCE.alePrice * ALE_BALANCE.alehouseDuesPermille / 1000);
    if (dues > 0) postings.push({ account: "cash", category: "stall_fee", amount: dues, sourceRefs: [{ type: "building", id, detail: `alehouse:${casks}` }] });
  }
  if (postings.length === 0) return next;
  const posted = postLedgerEntries(next, postings);
  return { ...next, treasuryCoin: posted.treasuryCoin, ledger: posted.ledger };
}

/** NG-8: a brother-in-law born lowers the expectation; the counterpart's broken non-infringement raises it. */
export const BROTHER_IN_LAW_CLAIM_LOSS = 30;
export const BREACHED_NON_INFRINGEMENT_GAIN = 15;
/** NG-8: the favour that talks the old lord out of a new will, pennies. */
export const WILL_FAVOUR_PENNIES = 120;

/** LG-2: a sealed charter — the town's one-off fine, the fee farm from then, the Crown's confirmation after a petition. */
charterFine: 300,
feeFarm: 200,
confirmationFine: 200,
/** LG-2: a refusal's backlash — at least this, the town's influence, or chapter 4's backlash and this much. */
backlashFloor: 30,

servedBonusFromLevel: 2,
servedHoldPermille: 1_000,
/** AL-7: ale's market price (pennies a cask), and the alehouse's dues a ledger period: this share of its sales. */
alePrice: 3,
alehouseDuesPermille: 200,
/**

 */
export function postLedgerEntries(
  state: Pick<GameState, "ledger" | "treasuryCoin" | "tick" | "scenarioId">,
  postings: readonly LedgerPosting[],
): { readonly ledger: Ledger; readonly treasuryCoin: number } {
  for (const posting of postings) {
    if (!Array.isArray(posting.sourceRefs) || posting.sourceRefs.length === 0) {
      throw new LedgerSourceError(`Ledger entry ${posting.category} has no source`);
    }
    if (!Number.isSafeInteger(posting.amount)) throw new RangeError(`Ledger amount must be whole pennies: ${posting.amount}`);
  }
  let ledger = state.ledger ?? openingLedger(state, "ledger_start");
  const previousCash = accountBalance(ledger, "cash");
  const entries = [...ledger.entries];
  let ordinal = ledger.nextEntryOrdinal;
  let postedCash = 0;
  for (const posting of postings) {
    entries.push({ ...posting, id: ledgerEntryId(ordinal), tick: state.tick });
    if (posting.account === "cash") postedCash += posting.amount;

// FAIL-3 (FL-1): a right lost to the overlord or the merchants pays its holder, not the treasury.
const markets = rightHeld(state, "market"), tolls = rightHeld(state, "tolls"), mill = rightHeld(state, "mill");
for (const market of [...state.buildings].filter(building => markets && building.kind === "market").sort((a, b) => a.id.localeCompare(b.id))) {
  const stalls = marketStalls(state, market);
  // FC-3/FC-4: a market charter lowers the dues (the right is a source of the posting).
  const right = stallFeeRightSource(state);
  // F2-A (WR-8): the market chosen over the wall raises the dues a quarter.
  // LM-E1 (TA-6 ③): in lord mode the lord's market dues scale the fee (1000‰ otherwise).
  const fee = Math.round(stalls * MONEY_BALANCE.stallFeePerStall * stallFeePermille(state) / 1000 * marketExpansionPermille(state) / 1000
    * agencyDuesPermille(state) / 1000);
  if (stalls > 0 && fee > 0) postings.push({ account: "cash", category: "stall_fee", amount: fee,
    sourceRefs: [buildingSource(market.id, `stalls:${stalls}`), ...(right === null ? [] : [right])] });
}

/** FC-3/FC-4: the stall fee under the granted rights, permille of the usual fee (the lowest right applies). */
export function stallFeePermille(state: Pick<GameState, "politics">): number {
  return Math.min(1000, ...(state.politics?.rights ?? []).map(right => right.stallFeePermille));
}

/** FC-4: the source a stall fee under a right carries, or null. */
export function stallFeeRightSource(state: Pick<GameState, "politics">): SourceRef | null {
  const right = (state.politics?.rights ?? []).find(entry => entry.stallFeePermille < 1000);
  return right === undefined ? null : { type: "right", id: right.id, detail: `stall_fee:${right.stallFeePermille}` };
}
